clickhouse-client --multiquery "
DROP TABLE IF EXISTS analytics.events_global_agg_mv;
DROP TABLE IF EXISTS analytics.events_global_agg;
DROP TABLE IF EXISTS analytics.events_by_region_day_mv;
DROP TABLE IF EXISTS analytics.events_by_region_day;

CREATE TABLE analytics.events_global_agg (
  k UInt8,
  total_state AggregateFunction(count),
  users_state AggregateFunction(uniq, String),
  revenue_state AggregateFunction(sum, Float64)
) ENGINE = Memory;

INSERT INTO analytics.events_global_agg
SELECT
  0 AS k,
  countState() AS total_state,
  uniqState(user_id) AS users_state,
  sumState(revenue) AS revenue_state
FROM analytics.events;

CREATE TABLE analytics.events_by_region_day (
  region String,
  day Date,
  cnt UInt64,
  sum_revenue Float64
) ENGINE = Memory;

INSERT INTO analytics.events_by_region_day
SELECT
  region,
  toDate(event_ts) AS day,
  count() AS cnt,
  sum(revenue) AS sum_revenue
FROM analytics.events
GROUP BY region, day;
"

